1	"use client";
2	
3	/* ============================================================================
4	   THE DESIGN SYSTEM SHOWCASE
5	   Lives inside the real shell, so navigating the documentation exercises the
6	   navigation being documented.
7	   ========================================================================= */
8	
9	import { useState } from "react";
10	import { AppShell, type NavGroup, type BottomNavItem } from "@/components/shell/AppShell";
11	import { ToastProvider } from "@/components/system/overlays";
12	import { Colour, Typography, Surfaces, Icons, Motion } from "./foundations";
13	import { Buttons, Forms, NavigationView, DataView, Overlays, States } from "./componentsview";
14	import { Ladder, Checkout, Setup, Detail, Inventory, TopologyView } from "./patterns";
15	import { Regions, Loaders, GameServers } from "./showpieces";
16	import { PageHeader, SectionRule, Container } from "@/components/system/primitives";
17	
18	const GROUPS: NavGroup[] = [
19	  { items: [{ id: "overview", label: "Overview", icon: "home" }] },
20	  {
21	    label: "Foundations",
22	    items: [
23	      { id: "colour", label: "Colour", icon: "region" },
24	      { id: "type", label: "Typography", icon: "files" },
25	      { id: "surfaces", label: "Surfaces", icon: "resources" },
26	      { id: "icons", label: "Iconography", icon: "deploy" },
27	      { id: "motion", label: "Motion", icon: "activity" },
28	    ],
29	  },
30	  {
31	    label: "Components",
32	    items: [
33	      { id: "buttons", label: "Buttons", icon: "play" },
34	      { id: "forms", label: "Forms", icon: "edit" },
35	      { id: "navigation", label: "Navigation", icon: "menu" },
36	      { id: "data", label: "Data display", icon: "storage" },
37	      { id: "overlays", label: "Overlays", icon: "console" },
38	      { id: "states", label: "States", icon: "info" },
39	    ],
40	  },
41	  {
42	    label: "Patterns",
43	    items: [
44	      { id: "regions", label: "Region selector", icon: "region" },
45	      { id: "games", label: "Game servers", icon: "game" },
46	      { id: "loaders", label: "Deploy loaders", icon: "deploy" },
47	      { id: "topology", label: "Topology", icon: "topology" },
48	      { id: "inventory", label: "Inventory", icon: "vps" },
49	      { id: "detail", label: "Resource detail", icon: "node" },
50	      { id: "checkout", label: "Two-stage checkout", icon: "billing" },
51	      { id: "ladder", label: "Deployment ladder", icon: "deploy" },
52	      { id: "setup", label: "Post-payment setup", icon: "check" },
53	    ],
54	  },
55	];
56	
57	/* Four thumb-reachable destinations plus More. In the real portal these would
58	   be Home, Resources, Deploy and Account. */
59	const BOTTOM: BottomNavItem[] = [
60	  { id: "overview", label: "Home", icon: "home" },
61	  { id: "inventory", label: "Resources", icon: "vps" },
62	  { id: "regions", label: "Deploy", icon: "deploy" },
63	  { id: "detail", label: "Detail", icon: "node" },
64	];
65	
66	function Overview({ go }: { go: (id: string) => void }) {
67	  return (
68	    <>
69	      <PageHeader
70	        eyebrow="Phase 2"
71	        title="Nxeon Design System"
72	        description="The foundation every later phase builds on: tokens, four surface archetypes, one icon family, one component library and the composed Nxeon patterns. Nothing here connects to a backend."
73	      />
74	
75	      <SectionRule label="What this is" />
76	      <div className="grid gap-3 lg:grid-cols-3">
77	        {[
78	          { t: "Foundations", d: "Colour with one meaning per token, a type scale with a real display tier, four surface archetypes, one icon family and a motion language.", to: "colour" },
79	          { t: "Components", d: "Buttons, forms, navigation, data display, overlays and states — each with default, hover, active, focus, disabled, loading, error and success.", to: "buttons" },
80	          { t: "Patterns", d: "The composed signatures: the inventory, the resource detail hierarchy, two-stage checkout, the deployment ladder and post-payment setup.", to: "inventory" },
81	        ].map((c) => (
82	          <button key={c.t} type="button" onClick={() => go(c.to)}
83	            className="nx-container-surface nx-lift px-5 py-4 text-left">
84	            <h3 className="text-h3 text-ink">{c.t}</h3>
85	            <p className="mt-2 text-body-sm text-ink-secondary">{c.d}</p>
86	          </button>
87	        ))}
88	      </div>
89	
90	      <SectionRule label="What it replaces" />
91	      <div className="grid grid-cols-2 gap-px overflow-hidden rounded-lg border border-hairline bg-hairline lg:grid-cols-4">
92	        {[
93	          ["21", "spellings of an inset panel, across ~145 places"],
94	          ["24", "modal implementations with zero focus traps"],
95	          ["60", "destructive actions confirmed by the browser dialog"],
96	          ["8", "tab-bar styles, two of which broke the Back button"],
97	          ["214", "hand-drawn icons at 18 stroke widths"],
98	          ["385", "hand-typed font sizes, and no display tier"],
99	          ["694", "uses of a text colour failing contrast on navy"],
100	          ["0", "toast systems, in a product with 19 bespoke ones"],
101	        ].map(([n, d]) => (
102	          <div key={d} className="bg-surface px-4 py-3.5">
103	            <span className="font-display text-metric tabular-nums text-signal-text">{n}</span>
104	            <span className="mt-1.5 block text-caption leading-snug text-ink-secondary">{d}</span>
105	          </div>
106	        ))}
107	      </div>
108	
109	      <SectionRule label="Isolation" />
110	      <Container className="px-5 py-4">
111	        <p className="max-w-[68ch] text-body-sm text-ink-secondary">
112	          This sandbox has no environment file, no database client, no payment, registrar, mail or
113	          hypervisor library, and makes no network request. Its entire dependency list is Next, React
114	          and React DOM. Every figure on screen comes from one mock file, and every address shown is
115	          from a documentation-reserved range, so nothing here can be confused with live customer
116	          infrastructure.
117	        </p>
118	      </Container>
119	    </>
120	  );
121	}
122	
123	export default function DesignSystemPage() {
124	  const [active, setActive] = useState("overview");
125	
126	  const view = () => {
127	    switch (active) {
128	      case "colour": return <Colour />;
129	      case "type": return <Typography />;
130	      case "surfaces": return <Surfaces />;
131	      case "icons": return <Icons />;
132	      case "motion": return <Motion />;
133	      case "buttons": return <Buttons />;
134	      case "forms": return <Forms />;
135	      case "navigation": return <NavigationView />;
136	      case "data": return <DataView />;
137	      case "overlays": return <Overlays />;
138	      case "states": return <States />;
139	      case "regions": return <Regions />;
140	      case "games": return <GameServers />;
141	      case "loaders": return <Loaders />;
142	      case "topology": return <TopologyView />;
143	      case "inventory": return <Inventory />;
144	      case "detail": return <Detail />;
145	      case "checkout": return <Checkout />;
146	      case "ladder": return <Ladder />;
147	      case "setup": return <Setup />;
148	      default: return <Overview go={setActive} />;
149	    }
150	  };
151	
152	  return (
153	    <ToastProvider>
154	      <AppShell groups={GROUPS} active={active} onNavigate={setActive} title="Nxeon" bottomNav={BOTTOM}>
155	        {view()}
156	      </AppShell>
157	    </ToastProvider>
158	  );
159	}
