1	@import "tailwindcss";
2	
3	/* ============================================================================
4	   NXEON DESIGN SYSTEM — TOKENS
5	   Phase 2. Single source of truth. No component may declare a raw colour,
6	   a raw font size, a raw radius, a raw duration or a raw z-index.
7	
8	   Navy is the Nxeon environment: this system is deliberately dark-first and
9	   commits to one visual world rather than inverting into a light theme.
10	   Every value is declared here so a second theme remains possible later
11	   without touching a single component.
12	   ========================================================================= */
13	
14	@theme {
15	  /* ---- Surface layers -------------------------------------------------- */
16	  --color-base: #070b14;        /* page ground */
17	  --color-surface: #0c1220;     /* panels, containers */
18	  --color-raised: #131b2b;      /* owned objects */
19	  --color-interactive: #1b2437; /* hover, inputs, pressed */
20	  --color-plate: #05080f;       /* recessed technical data */
21	  --color-scrim: #03060c;       /* behind overlays */
22	
23	  /* ---- Hairlines. Blue-grey, never neutral grey ------------------------ */
24	  --color-hairline: #1e2839;
25	  --color-hairline-strong: #2c3a52;
26	  --color-hairline-hover: #3a4a66;      /* hairline-strong's hover step */
27	
28	  /* Hover step above --color-interactive, for controls already on it. */
29	  --color-interactive-hover: #22304a;
30	
31	  /* ---- Text. Every value verified for AA on --color-surface ------------ */
32	  --color-ink: #e7edf6;           /* 15.6:1  primary */
33	  --color-ink-secondary: #a9b6ca; /*  9.2:1  secondary */
34	  --color-ink-muted: #8494ac;     /*  6.1:1  muted — replaces the 4.0:1 tone */
35	  --color-ink-disabled: #5b6880;  /*  3.3:1  disabled only, never information */
36	  --color-ink-inverse: #070b14;
37	
38	  /* ---- Signal. The brand accent, and the one action on screen ---------- */
39	  --color-signal: #1e63d6;        /* fill; white on it = 5.5:1 */
40	  --color-signal-hover: #2e7bf6;
41	  --color-signal-press: #1750b4;
42	  --color-signal-text: #6ba5ff;   /* 7.6:1  signal as text or icon */
43	  --color-signal-edge: #2e7bf6;
44	
45	  /* ---- Data. Charts, meters, topology. Never an action ----------------- */
46	  --color-data: #2bb3ce;
47	  --color-data-2: #6ba5ff;
48	  --color-data-3: #3fcb9e;
49	  --color-data-4: #f0b44a;
50	  --color-data-5: #a88bff;
51	
52	  /* ---- Semantic state. Separate from the accent, always -------------- */
53	  --color-success: #0e7a5c;
54	  --color-success-text: #3fcb9e;  /* 9.3:1 */
55	  --color-warning: #8a5d10;
56	  --color-warning-text: #f0b44a;  /* 11.0:1 */
57	  --color-danger: #a83226;
58	  --color-danger-text: #ff8a7d;   /* 8.3:1 */
59	  --color-info: #1e63d6;
60	  --color-info-text: #6ba5ff;
61	
62	  /* ---- Violet. Reserved: AI and Build surfaces only -------------------- */
63	  --color-ai: #6b4be8;
64	  --color-ai-text: #a88bff;       /* 6.9:1 */
65	
66	  /* ---- THE BRAND GRADIENT ---------------------------------------------
67	     Sampled from the Nxeon lockup: the mark runs blue -> violet. The ramp
68	     is extended to a magenta terminus so the brand gradient carries the
69	     magenta end you asked for while still matching the logo exactly.
70	     Three stops, one place. Change `brand-c` to dial the magenta. */
71	  --color-brand-a: #3b6be8;       /* logo blue, left of the mark */
72	  --color-brand-b: #7b3fef;       /* logo violet, right of the mark */
73	  --color-brand-c: #e5197e;       /* magenta terminus — swap for the exact hex */
74	
75	  /* Text and icons sitting ON a brand fill are always this. */
76	  --color-on-brand: #ffffff;
77	
78	  /* Ink-safe brand stops, derived — never hand-tuned, so they follow the
79	     tokens when the real magenta hex lands. White on pure brand-c measures
80	     4.40:1 (fails AA for body-size labels) and white on neon cyan is 1.51:1,
81	     so any brand fill that carries white text ends on these instead:
82	       c-ink   ~5.7:1 under white     glint   ~4.6:1 under white */
83	  --color-brand-c-ink: color-mix(in srgb, var(--color-brand-c) 82%, var(--color-base));
84	  --color-brand-glint: color-mix(in srgb, var(--color-neon-cyan) 20%, var(--color-brand-b));
85	
86	  /* ---- NEON --------------------------------------------------------
87	     Deliberate, and rationed. Neon is allowed on exactly three things:
88	     a live resource, the brand mark, and a primary brand moment such as
89	     the deploy action. It is never ambient and never decorative. */
90	  /* ---- PRODUCT IDENTITY -------------------------------------------------
91	     A third colour axis, separate from signal (the action) and semantic
92	     (the state). A product's hue is INFORMATION: it makes a VPS card, a VPS
93	     row and a VPS breadcrumb recognisable as the same thing at a glance, and
94	     it is what stops a nine-product catalogue reading as nine grey boxes.
95	     Rule: identity colour may tint an icon, a hairline or a wash. It may
96	     never become a button — the action stays signal or brand. */
97	  --color-p-vps:     #5c9bff;   /* azure     — compute */
98	  --color-p-game:    #ff5ca8;   /* magenta   — energetic, matches the brand terminus */
99	  --color-p-hosting: #34d3e6;   /* cyan      — websites */
100	  --color-p-domain:  #3fcb9e;   /* jade      — identity, trust */
101	  --color-p-email:   #f0b44a;   /* amber     — communication */
102	  --color-p-storage: #8b9dff;   /* periwinkle— block storage */
103	  --color-p-site:    #7fd957;   /* spring    — the builder */
104	  --color-p-cloud:   #ff8a5c;   /* coral     — NxCloud */
105	  --color-p-free:    #58d95c;   /* green     — the free tier */
106	
107	  --color-neon-cyan: #34e6ff;
108	  --color-neon-magenta: #ff2f9a;
109	
110	  /* ---- Type ------------------------------------------------------------ */
111	  --font-display: var(--font-archivo), "Helvetica Neue", Arial, sans-serif;
112	  --font-sans: var(--font-plex-sans), ui-sans-serif, system-ui, sans-serif;
113	  --font-mono: var(--font-plex-mono), ui-monospace, "SFMono-Regular", Menlo, monospace;
114	
115	  /* Scale. Nothing below 12px, and 12px is reserved for tracked labels.
116	     The old portal's 10px and 11px steps do not exist here by design. */
117	  --text-display: 2.25rem;      --text-display--line-height: 1.04;  --text-display--letter-spacing: -0.028em;  --text-display--font-weight: 700;
118	  --text-h1: 1.75rem;           --text-h1--line-height: 1.12;       --text-h1--letter-spacing: -0.022em;       --text-h1--font-weight: 700;
119	  --text-h2: 1.375rem;          --text-h2--line-height: 1.2;        --text-h2--letter-spacing: -0.016em;       --text-h2--font-weight: 600;
120	  --text-h3: 1.0625rem;         --text-h3--line-height: 1.3;        --text-h3--letter-spacing: -0.008em;       --text-h3--font-weight: 600;
121	  --text-h4: 0.9375rem;         --text-h4--line-height: 1.35;       --text-h4--letter-spacing: 0em;            --text-h4--font-weight: 600;
122	  --text-body: 0.9375rem;       --text-body--line-height: 1.6;
123	  --text-body-sm: 0.875rem;     --text-body-sm--line-height: 1.55;
124	  --text-caption: 0.8125rem;    --text-caption--line-height: 1.5;
125	  --text-label: 0.75rem;        --text-label--line-height: 1.2;     --text-label--letter-spacing: 0.11em;      --text-label--font-weight: 600;
126	  --text-code: 0.875rem;        --text-code--line-height: 1.5;
127	  --text-metric: 1.75rem;       --text-metric--line-height: 1;      --text-metric--letter-spacing: -0.03em;    --text-metric--font-weight: 700;
128	  --text-metric-sm: 1.125rem;   --text-metric-sm--line-height: 1.1; --text-metric-sm--letter-spacing: -0.02em; --text-metric-sm--font-weight: 600;
129	
130	  /* ---- Radius. Small and deliberate. The notch is the object signature -- */
131	  --radius-xs: 2px;
132	  --radius-sm: 4px;
133	  --radius-md: 6px;
134	  --radius-lg: 10px;
135	  --radius-pill: 999px;
136	  --nx-notch: 15px;
137	
138	  /* ---- Elevation. Separation is by layer and hairline first ------------ */
139	  --shadow-plate: inset 0 1px 0 0 rgb(255 255 255 / 0.03);
140	  --shadow-raised: 0 1px 2px 0 rgb(0 0 0 / 0.4);
141	  --shadow-overlay: 0 24px 64px -20px rgb(0 0 0 / 0.75), 0 0 0 1px rgb(44 58 82 / 0.7);
142	  --shadow-dock: 0 -12px 32px -16px rgb(0 0 0 / 0.7);
143	
144	  /* ---- Glow. Rationed, and each one has a named owner ----------------- */
145	  --nx-glow-live: 0 0 0 1px rgb(63 203 158 / 0.35), 0 0 12px -2px rgb(63 203 158 / 0.45);
146	  --nx-glow-brand: 0 0 24px -6px rgb(123 63 239 / 0.55), 0 0 48px -18px rgb(229 25 126 / 0.4);
147	  --nx-glow-neon: 0 0 10px -1px rgb(52 230 255 / 0.55);
148	
149	  /* ---- Motion ---------------------------------------------------------- */
150	  --nx-dur-1: 120ms;   /* state: hover, press, colour */
151	  --nx-dur-2: 180ms;   /* movement: reveal, tab, row */
152	  --nx-dur-3: 240ms;   /* surface: drawer, modal, wizard */
153	  --nx-ease: cubic-bezier(0.2, 0, 0, 1);
154	  --nx-ease-out: cubic-bezier(0.16, 1, 0.3, 1);
155	  --nx-ease-in: cubic-bezier(0.7, 0, 0.84, 0);
156	
157	  /* ---- Z-index. The documented stacking contract. Nothing invents a tier */
158	  --nx-z-base: 0;
159	  --nx-z-raised: 10;
160	  --nx-z-sticky: 20;
161	  --nx-z-scrim: 30;   /* the drawer's backdrop sits BELOW the drawer */
162	  --nx-z-rail: 40;    /* ...and the drawer above it, or the nav is untappable */
163	  --nx-z-overlay: 50;
164	  --nx-z-toast: 60;
165	  --nx-z-tooltip: 70;
166	
167	  /* ---- Focus ----------------------------------------------------------- */
168	  --nx-focus-width: 2px;
169	  --nx-focus-offset: 2px;
170	
171	  /* ---- Breakpoints (Tailwind defaults, stated so they are a contract) --- */
172	  --breakpoint-sm: 40rem;
173	  --breakpoint-md: 48rem;
174	  --breakpoint-lg: 64rem;
175	  --breakpoint-xl: 80rem;
176	  --breakpoint-2xl: 96rem;
177	
178	  /* ---- Keyframes ------------------------------------------------------- */
179	  --animate-nx-filament: nx-filament 2.4s ease-in-out infinite;
180	  --animate-nx-rise: nx-rise var(--nx-dur-3) var(--nx-ease-out) both;
181	  --animate-nx-fade: nx-fade var(--nx-dur-2) var(--nx-ease) both;
182	  --animate-nx-slide-right: nx-slide-right var(--nx-dur-3) var(--nx-ease-out) both;
183	  --animate-nx-slide-left: nx-slide-left var(--nx-dur-3) var(--nx-ease-out) both;
184	  --animate-nx-check: nx-check var(--nx-dur-3) var(--nx-ease-out) both;
185	  --animate-nx-sweep: nx-sweep 1.4s linear infinite;
186	  --animate-nx-pulse: nx-pulse 2s ease-in-out infinite;
187	  --animate-nx-trace: nx-trace 2.6s ease-in-out infinite;
188	  --animate-nx-node: nx-node 2.4s ease-in-out infinite;
189	  --animate-nx-grad-drift: nx-grad-drift 9s ease-in-out infinite;
190	  --animate-nx-scan: nx-scan 2.2s var(--nx-ease) infinite;
191	}
192	
193	@keyframes nx-filament {
194	  0%, 100% { transform: translateY(-100%); }
195	  50%      { transform: translateY(100%); }
196	}
197	@keyframes nx-rise {
198	  from { opacity: 0; transform: translateY(6px); }
199	  to   { opacity: 1; transform: none; }
200	}
201	@keyframes nx-fade {
202	  from { opacity: 0; }
203	  to   { opacity: 1; }
204	}
205	@keyframes nx-slide-right {
206	  from { transform: translateX(100%); }
207	  to   { transform: none; }
208	}
209	@keyframes nx-slide-left {
210	  from { transform: translateX(-100%); }
211	  to   { transform: none; }
212	}
213	@keyframes nx-check {
214	  from { stroke-dashoffset: 22; }
215	  to   { stroke-dashoffset: 0; }
216	}
217	@keyframes nx-sweep {
218	  from { transform: translateX(-100%); }
219	  to   { transform: translateX(300%); }
220	}
221	@keyframes nx-pulse {
222	  0%, 100% { opacity: 1; }
223	  50%      { opacity: 0.45; }
224	}
225	/* A packet travelling a topology path. */
226	@keyframes nx-trace {
227	  0%   { stroke-dashoffset: 220; opacity: 0; }
228	  12%  { opacity: 1; }
229	  88%  { opacity: 1; }
230	  100% { stroke-dashoffset: 0; opacity: 0; }
231	}
232	/* A node breathing on the map. */
233	@keyframes nx-node {
234	  0%, 100% { r: 3;   opacity: 0.9; }
235	  50%      { r: 4.6; opacity: 0.5; }
236	}
237	/* Slow drift across a brand gradient — the only ambient motion allowed. */
238	@keyframes nx-grad-drift {
239	  0%, 100% { background-position: 0% 50%; }
240	  50%      { background-position: 100% 50%; }
241	}
242	/* A provisioning scan line. */
243	/* --- deployment loader primitives --- */
244	@keyframes nx-block-in {
245	  0%, 12%  { opacity: 0; transform: translateY(5px) scaleY(0.4); }
246	  26%, 88% { opacity: 1; transform: none; }
247	  100%     { opacity: 0.35; transform: none; }
248	}
249	@keyframes nx-scanline {
250	  0%   { transform: translateY(-8%); opacity: 0; }
251	  15%  { opacity: 1; }
252	  85%  { opacity: 1; }
253	  100% { transform: translateY(108%); opacity: 0; }
254	}
255	@keyframes nx-ring-out {
256	  0%   { transform: scale(0.25); opacity: 0.85; }
257	  100% { transform: scale(1); opacity: 0; }
258	}
259	@keyframes nx-drop-in {
260	  0%, 10%  { opacity: 0; transform: translate(0,-14px); }
261	  30%, 82% { opacity: 1; transform: none; }
262	  100%     { opacity: 0; transform: translate(0,6px); }
263	}
264	@keyframes nx-tick-on {
265	  0%, 40%   { opacity: 0.2; }
266	  55%, 100% { opacity: 1; }
267	}
268	@keyframes nx-deploy-sweep {
269	  0%   { transform: translateX(-130%) skewX(-12deg); }
270	  100% { transform: translateX(130%) skewX(-12deg); }
271	}
272	@keyframes nx-scan {
273	  0%   { transform: translateY(-100%); opacity: 0; }
274	  20%  { opacity: 1; }
275	  80%  { opacity: 1; }
276	  100% { transform: translateY(400%); opacity: 0; }
277	}
278	
279	/* ============================================================================
280	   BASE
281	   ========================================================================= */
282	@layer base {
283	  * { border-color: var(--color-hairline); }
284	
285	  html { -webkit-text-size-adjust: 100%; }
286	
287	  body {
288	    background-color: var(--color-base);
289	    color: var(--color-ink);
290	    font-family: var(--font-sans);
291	    font-size: var(--text-body);
292	    line-height: 1.6;
293	    -webkit-font-smoothing: antialiased;
294	    text-rendering: optimizeLegibility;
295	  }
296	
297	  /* Atmosphere: one very low-contrast field. It must disappear behind
298	     content — it is never a feature, and it never moves. */
299	  body::before {
300	    content: "";
301	    position: fixed;
302	    inset: 0;
303	    pointer-events: none;
304	    z-index: 0;
305	    background:
306	      radial-gradient(1100px 620px at 12% -8%, rgb(30 99 214 / 0.055), transparent 70%),
307	      radial-gradient(900px 520px at 100% 0%, rgb(43 179 206 / 0.035), transparent 70%);
308	  }
309	
310	  h1, h2, h3, h4, h5, h6 { font-family: var(--font-display); text-wrap: balance; }
311	
312	  /* One focus style, globally. The old portal had none. */
313	  :focus-visible {
314	    outline: var(--nx-focus-width) solid var(--color-signal-edge);
315	    outline-offset: var(--nx-focus-offset);
316	    border-radius: var(--radius-xs);
317	  }
318	  :focus:not(:focus-visible) { outline: none; }
319	
320	  ::selection { background: rgb(46 123 246 / 0.32); color: var(--color-ink); }
321	
322	  ::-webkit-scrollbar { width: 10px; height: 10px; }
323	  ::-webkit-scrollbar-track { background: var(--color-base); }
324	  ::-webkit-scrollbar-thumb {
325	    background: var(--color-hairline-strong);
326	    border-radius: var(--radius-pill);
327	    border: 2px solid var(--color-base);
328	  }
329	  ::-webkit-scrollbar-thumb:hover { background: var(--color-hairline-hover); }
330	
331	  /* Numbers never jitter. */
332	  table, .nx-tabular { font-variant-numeric: tabular-nums; }
333	}
334	
335	/* ============================================================================
336	   THE FOUR SURFACE ARCHETYPES
337	   The whole point: a border means "separate object". It is spent by role.
338	   ========================================================================= */
339	@layer components {
340	
341	  /* 1 — OBJECT. A thing the customer owns.
342	     Two clipped layers, not a clipped border: the outer layer paints the
343	     hairline, the inner layer paints the surface 1px inside it. That gives
344	     a real stroke along the chamfer — a single clip-path would cut the
345	     border off and leave the notch reading as a rendering artifact. */
346	  .nx-object {
347	    --nx-object-edge: var(--color-hairline);
348	    position: relative;
349	    isolation: isolate;
350	    background-color: var(--nx-object-edge);
351	    /* No box-shadow here: clip-path clips everything the element paints,
352	       including outer shadows — a shadow on this class can never render. */
353	    clip-path: polygon(
354	      var(--nx-notch) 0, 100% 0, 100% 100%, 0 100%, 0 var(--nx-notch)
355	    );
356	    transition: background-color var(--nx-dur-1) var(--nx-ease);
357	  }
358	  /* Focus on a clipped surface: the global outline sits outside the border
359	     box, so the clip-path swallows it whole. Instead the edge layer itself
360	     becomes the ring — 2px of signal blue along the full notched outline. */
361	  .nx-object:focus-visible {
362	    outline: none;
363	    --nx-object-edge: var(--color-signal-edge);
364	    background-image: none; /* the ring wins over a selected gradient edge */
365	  }
366	  .nx-object:focus-visible::before {
367	    inset: 2px;
368	    clip-path: polygon(
369	      calc(var(--nx-notch) - 2px) 0, 100% 0, 100% 100%, 0 100%,
370	      0 calc(var(--nx-notch) - 2px)
371	    );
372	  }
373	  .nx-object::before {
374	    content: "";
375	    position: absolute;
376	    inset: 1px;
377	    z-index: 0;
378	    background-color: var(--color-raised);
379	    clip-path: polygon(
380	      calc(var(--nx-notch) - 1px) 0, 100% 0, 100% 100%, 0 100%,
381	      0 calc(var(--nx-notch) - 1px)
382	    );
383	    transition: background-color var(--nx-dur-1) var(--nx-ease);
384	  }
385	  /* Content sits above the inner fill layer. */
386	  .nx-object > * { position: relative; z-index: 1; }
387	
388	  .nx-object-interactive:hover { --nx-object-edge: var(--color-hairline-strong); }
389	  .nx-object-interactive:hover::before { background-color: var(--color-interactive); }
390	
391	  /* Selected object: the whole edge picks up the brand ramp, so the outline
392	     carries the selection rather than a heavy border or a (clipped, hence
393	     impossible) glow doing it. background-image beats the base
394	     background-color, so the gradient only needs declaring here. */
395	  .nx-object-selected {
396	    --nx-object-edge: var(--color-brand-b);
397	    background-image: linear-gradient(
398	      135deg, var(--color-brand-a), var(--color-brand-b) 55%, var(--color-brand-c)
399	    );
400	  }
401	  .nx-object-selected::before { background-color: color-mix(in oklab, var(--color-brand-b) 9%, var(--color-raised)); }
402	
403	  /* 2 — CONTAINER. Groups information without claiming to be an object. */
404	  .nx-container-surface {
405	    background-color: var(--color-surface);
406	    border: 1px solid var(--color-hairline);
407	    border-radius: var(--radius-lg);
408	  }
409	
410	  /* 3 — PLATE. Recessed. Technical values live here and nowhere else. */
411	  .nx-plate {
412	    background-color: var(--color-plate);
413	    border: 1px solid var(--color-hairline);
414	    border-radius: var(--radius-md);
415	    box-shadow: var(--shadow-plate);
416	    font-family: var(--font-mono);
417	    font-size: var(--text-code);
418	    color: var(--color-ink-secondary);
419	  }
420	
421	  /* 4 — RULE. A labelled hairline. The primary grouping device, and the
422	     reason most of these sections need no border at all. */
423	  .nx-rule {
424	    display: flex;
425	    align-items: center;
426	    gap: 0.7rem;
427	  }
428	  .nx-rule::after {
429	    content: "";
430	    flex: 1 1 auto;
431	    height: 1px;
432	    background-color: var(--color-hairline);
433	  }
434	  .nx-rule > .nx-rule-label {
435	    font-family: var(--font-display);
436	    font-size: var(--text-label);
437	    font-weight: 600;
438	    letter-spacing: 0.11em;
439	    text-transform: uppercase;
440	    color: var(--color-ink-muted);
441	    white-space: nowrap;
442	  }
443	
444	  /* ---- The status filament --------------------------------------------
445	     Starts where the notch ends, so the chamfer and the filament read as
446	     one deliberate corner treatment rather than two clashing devices. */
447	  .nx-filament {
448	    position: absolute;
449	    left: 1px; top: var(--nx-notch); bottom: 1px;
450	    width: 2px;
451	    z-index: 2;
452	    overflow: hidden;
453	    background-color: currentColor;
454	  }
455	  .nx-filament[data-live="true"] {
456	    box-shadow: var(--nx-glow-neon);
457	  }
458	  .nx-filament[data-live="true"]::after {
459	    content: "";
460	    position: absolute;
461	    inset: 0;
462	    background: linear-gradient(to bottom, transparent, rgb(255 255 255 / 0.95), transparent);
463	    animation: var(--animate-nx-filament);
464	  }
465	
466	  /* ---- Product identity ------------------------------------------------
467	     `--p` is set per card; the tile, the edge and the wash all read from it,
468	     so one variable colours the whole object. Identity colour may tint an
469	     icon, a hairline or a wash — it may never become a button, because the
470	     action stays signal or brand. */
471	  .nx-p-tile {
472	    color: var(--p);
473	    background-color: color-mix(in srgb, var(--p) 14%, transparent);
474	    border: 1px solid color-mix(in srgb, var(--p) 32%, transparent);
475	  }
476	  .nx-p-card {
477	    position: relative;
478	    transition: border-color var(--nx-dur-1) var(--nx-ease),
479	                transform var(--nx-dur-2) var(--nx-ease),
480	                box-shadow var(--nx-dur-2) var(--nx-ease);
481	  }
482	  .nx-p-card::before {
483	    content: "";
484	    position: absolute;
485	    inset: 0;
486	    pointer-events: none;
487	    opacity: 0;
488	    background: radial-gradient(120% 80% at 50% 0%, color-mix(in srgb, var(--p) 16%, transparent), transparent 70%);
489	    transition: opacity var(--nx-dur-2) var(--nx-ease);
490	  }
491	  .nx-p-card:hover {
492	    transform: translateY(-2px);
493	    border-color: color-mix(in srgb, var(--p) 45%, transparent);
494	    box-shadow: 0 0 0 1px color-mix(in srgb, var(--p) 22%, transparent),
495	                0 22px 55px -30px color-mix(in srgb, var(--p) 75%, transparent);
496	  }
497	  .nx-p-card:hover::before { opacity: 1; }
498	  .nx-p-card > * { position: relative; z-index: 1; }
499	  /* The identity edge: a top rule in the product's own colour. */
500	  .nx-p-edge::after {
501	    content: "";
502	    position: absolute;
503	    inset-inline: 0;
504	    top: 0;
505	    height: 2px;
506	    z-index: 2;
507	    background: linear-gradient(90deg, transparent, var(--p), transparent);
508	    opacity: 0.8;
509	  }
510	
511	  /* ---- Brand gradient utilities ---------------------------------------
512	     nx-grad-brand is a FILL that carries white text (badges, chips, the
513	     active nav mark), so it ends on the ink-safe magenta. The pure ramp
514	     lives in nx-grad-text and nx-grad-rule, which never sit under text. */
515	  .nx-grad-brand {
516	    background-image: linear-gradient(
517	      100deg,
518	      var(--color-brand-a) 0%,
519	      var(--color-brand-b) 52%,
520	      var(--color-brand-c-ink) 100%
521	    );
522	  }
523	  .nx-grad-text {
524	    background-image: linear-gradient(
525	      100deg, var(--color-brand-a), var(--color-brand-b) 55%, var(--color-brand-c)
526	    );
527	    -webkit-background-clip: text;
528	    background-clip: text;
529	    color: transparent;
530	  }
531	  /* A 1px brand rule — the gradient as a hairline rather than a fill. */
532	  .nx-grad-rule {
533	    height: 1px;
534	    background-image: linear-gradient(
535	      90deg, transparent, var(--color-brand-a), var(--color-brand-b), var(--color-brand-c), transparent
536	    );
537	  }
538	
539	  /* ---- THE DEPLOY BUTTON ----------------------------------------------
540	     The hover behaviour kept verbatim from the production portal, because it
541	     is the one interaction the owner wants carried forward: an animated
542	     gradient shift, a one-shot shimmer sweep, a 1px lift, and an arrow nudge.
543	     Only the palette changes — it now rides the new brand ramp. */
544	  .nx-deploy {
545	    position: relative;
546	    overflow: hidden;
547	    border-radius: var(--radius-pill);
548	    color: var(--color-on-brand);
549	    /* The moving ramp behaviour is kept verbatim; only the two stops that
550	       failed AA under the white label changed. Pure neon cyan measured
551	       1.51:1 beneath the label, so the cyan now rides the hover shimmer
552	       (below) while the base ramp uses the deepened glint (~4.6:1), and
553	       the magenta stop is the ink-safe one (~5.7:1). */
554	    background-image: linear-gradient(
555	      110deg,
556	      var(--color-brand-a), var(--color-brand-b), var(--color-brand-glint),
557	      var(--color-brand-c-ink), var(--color-brand-a)
558	    );
559	    background-size: 220% 100%;
560	    background-position: 0% 0;
561	    box-shadow: 0 8px 26px -8px rgb(123 63 239 / 0.55),
562	                0 4px 30px -10px rgb(229 25 126 / 0.45),
563	                inset 0 1px 0 0 rgb(255 255 255 / 0.18);
564	    transition: transform 200ms ease, box-shadow 200ms ease, background-position 600ms ease;
565	  }
566	  .nx-deploy:hover {
567	    transform: translateY(-1px);
568	    background-position: 100% 0;
569	    box-shadow: 0 12px 34px -8px rgb(123 63 239 / 0.7),
570	                0 8px 40px -10px rgb(229 25 126 / 0.6),
571	                inset 0 1px 0 0 rgb(255 255 255 / 0.25);
572	  }
573	  .nx-deploy::before {
574	    content: "";
575	    position: absolute;
576	    inset-block: 0;
577	    left: 0;
578	    width: 60%;
579	    pointer-events: none;
580	    /* The one-shot sweep, now carrying the neon cyan as a translucent
581	       glint — bright for 750ms without ever settling under the label. */
582	    background: linear-gradient(
583	      90deg, transparent,
584	      color-mix(in srgb, var(--color-neon-cyan) 55%, rgb(255 255 255 / 0.65)) ,
585	      transparent
586	    );
587	    opacity: 0.45;
588	    transform: translateX(-130%) skewX(-12deg);
589	  }
590	  .nx-deploy:hover::before { animation: nx-deploy-sweep 750ms ease; }
591	  .nx-deploy .nx-arrow { transition: transform 250ms ease; }
592	  .nx-deploy:hover .nx-arrow { transform: translateX(3px); }
593	
594	  /* ---- GLOW ------------------------------------------------------------
595	     Glow is a property of importance, not decoration. Three levels, and a
596	     surface may carry at most one. */
597	  .nx-glow-soft {
598	    box-shadow: 0 0 0 1px rgb(123 63 239 / 0.12),
599	                0 18px 50px -28px rgb(123 63 239 / 0.55);
600	  }
601	  .nx-glow-card {
602	    box-shadow: 0 0 0 1px rgb(123 63 239 / 0.16),
603	                0 20px 60px -30px rgb(123 63 239 / 0.7),
604	                0 10px 40px -26px rgb(229 25 126 / 0.45);
605	  }
606	  .nx-glow-hero {
607	    box-shadow: 0 0 0 1px rgb(123 63 239 / 0.2),
608	                0 30px 90px -40px rgb(123 63 239 / 0.8),
609	                0 20px 70px -34px rgb(229 25 126 / 0.6),
610	                inset 0 1px 0 0 rgb(255 255 255 / 0.06);
611	  }
612	  /* A card that lifts and lights on hover. */
613	  .nx-lift {
614	    transition: transform var(--nx-dur-2) var(--nx-ease),
615	                box-shadow var(--nx-dur-2) var(--nx-ease);
616	  }
617	  .nx-lift:hover {
618	    transform: translateY(-2px);
619	    box-shadow: 0 0 0 1px rgb(123 63 239 / 0.22),
620	                0 24px 60px -28px rgb(123 63 239 / 0.75),
621	                0 12px 44px -26px rgb(229 25 126 / 0.5);
622	  }
623	  /* A hero surface: gradient hairline on top, aura behind. */
624	  .nx-hero {
625	    position: relative;
626	    isolation: isolate;
627	  }
628	  .nx-hero::after {
629	    content: "";
630	    position: absolute;
631	    inset: -30% -10% auto -10%;
632	    height: 70%;
633	    z-index: -1;
634	    pointer-events: none;
635	    background:
636	      radial-gradient(50% 60% at 22% 40%, rgb(59 107 232 / 0.28), transparent 70%),
637	      radial-gradient(45% 55% at 78% 30%, rgb(229 25 126 / 0.22), transparent 70%);
638	    filter: blur(6px);
639	  }
640	
641	  /* Primary brand action. The sweep is the one place a gradient moves. */
642	  .nx-cta {
643	    position: relative;
644	    overflow: hidden;
645	    /* Ends on the ink-safe magenta: this fill always carries a white label. */
646	    background-image: linear-gradient(
647	      100deg, var(--color-brand-a), var(--color-brand-b) 55%, var(--color-brand-c-ink)
648	    );
649	    box-shadow: var(--nx-glow-brand);
650	  }
651	  .nx-cta::after {
652	    content: "";
653	    position: absolute;
654	    inset: 0;
655	    background: linear-gradient(100deg, transparent 20%, rgb(255 255 255 / 0.22), transparent 80%);
656	    transform: translateX(-120%);
657	  }
658	  .nx-cta:hover::after { animation: nx-sweep 900ms var(--nx-ease) 1; }
659	
660	  /* ---- Precision grid: the infrastructure backdrop ---------------------
661	     A drawn field, not a decorative blob. Used behind topology and brand
662	     moments only, and it never sits under running text. */
663	  .nx-grid-field {
664	    background-image:
665	      linear-gradient(to right, rgb(123 63 239 / 0.055) 1px, transparent 1px),
666	      linear-gradient(to bottom, rgb(123 63 239 / 0.055) 1px, transparent 1px);
667	    background-size: 28px 28px;
668	  }
669	  .nx-grid-mask {
670	    -webkit-mask-image: radial-gradient(120% 90% at 50% 0%, #000 30%, transparent 78%);
671	    mask-image: radial-gradient(120% 90% at 50% 0%, #000 30%, transparent 78%);
672	  }
673	
674	  /* ---- Focus ring used inside composite controls ----------------------- */
675	  .nx-ring-focus:focus-within {
676	    outline: var(--nx-focus-width) solid var(--color-signal-edge);
677	    outline-offset: var(--nx-focus-offset);
678	  }
679	}
680	
681	/* ============================================================================
682	   REDUCED MOTION
683	   Global by default; nothing opts back in except opacity. The old portal
684	   guarded 8 of 69 animations — here the default is off.
685	   ========================================================================= */
686	/* Coarse pointers get a 44px minimum on every control, without inflating
687	   the same control on a desktop where a cursor is precise. */
688	@media (pointer: coarse) {
689	  button, [role="switch"], a[role="button"], summary {
690	    min-height: 44px;
691	  }
692	  button.nx-inline, .nx-inline button { min-height: 0; }
693	}
694	
695	@media (prefers-reduced-motion: reduce) {
696	  *, *::before, *::after {
697	    animation-duration: 0.001ms !important;
698	    animation-delay: 0s !important;
699	    animation-iteration-count: 1 !important;
700	    /* Hold the FINAL keyframe. Without this, looping build animations whose
701	       base state is opacity 0 (the deploy loaders' rack slots, cubes, tick
702	       dots) snap back to invisible after their 0.001ms run and the loader
703	       renders as an empty shell. With `forwards` every loader shows its
704	       completed static frame instead. */
705	    animation-fill-mode: forwards !important;
706	    transition-duration: 0.001ms !important;
707	    scroll-behavior: auto !important;
708	  }
709	}
