const { chromium } = require("/opt/nxeon/node_modules/playwright");
const path = require("path");

const BASE = "http://localhost:3010/ds/design";
const OUT = "/tmp/claude-0/-root/ec6fa978-d80b-4147-9982-eea470598e2c/scratchpad/nxeon-design-package";

async function clickNav(page, label) {
  const nav = page.getByRole("navigation", { name: "Primary" });
  await nav.getByRole("button", { name: label, exact: true }).click();
  await page.waitForTimeout(500);
}

async function shot(page, outPath) {
  await page.screenshot({ path: outPath, fullPage: true });
  console.log("saved", outPath);
}

(async () => {
  const browser = await chromium.launch();
  const context = await browser.newContext({
    viewport: { width: 1440, height: 900 },
    deviceScaleFactor: 2,
    reducedMotion: "reduce",
  });
  const page = await context.newPage();
  await page.goto(BASE, { waitUntil: "networkidle" });
  await page.waitForTimeout(500);

  // 1. Shell overview (default landing view — shows rail nav + top bar + content)
  await shot(page, path.join(OUT, "components", "shell-overview.png"));

  // 2. Tokens: Colour
  await clickNav(page, "Colour");
  await shot(page, path.join(OUT, "tokens", "tokens-colour.png"));

  // 3. Tokens: Typography
  await clickNav(page, "Typography");
  await shot(page, path.join(OUT, "tokens", "tokens-typography.png"));

  // 4. Surfaces (components)
  await clickNav(page, "Surfaces");
  await shot(page, path.join(OUT, "components", "surfaces.png"));

  // 5. Iconography -> the combined icon reference sheet. Bump to the largest
  // optical size (20px) via the segmented control for a clearer sheet.
  await clickNav(page, "Iconography");
  const seg20 = page.getByRole("radio", { name: "20" }).first();
  const hasRadio = await seg20.count();
  if (hasRadio) {
    await seg20.click();
  } else {
    // Fallback: segmented control might expose buttons instead of radios.
    const btn20 = page.getByRole("button", { name: "20", exact: true }).first();
    if (await btn20.count()) await btn20.click();
  }
  await page.waitForTimeout(300);
  await shot(page, path.join(OUT, "icons", "icon-sheet.png"));

  // 6. Motion (bonus foundations layer)
  await clickNav(page, "Motion");
  await shot(page, path.join(OUT, "components", "motion.png"));

  // 7. Controls: Buttons
  await clickNav(page, "Buttons");
  await shot(page, path.join(OUT, "components", "controls-buttons.png"));

  // 8. Controls: Forms
  await clickNav(page, "Forms");
  await shot(page, path.join(OUT, "components", "controls-forms.png"));

  // 9. Navigation
  await clickNav(page, "Navigation");
  await shot(page, path.join(OUT, "components", "navigation.png"));

  // 10. Data display
  await clickNav(page, "Data display");
  await shot(page, path.join(OUT, "components", "data.png"));

  // 11. Overlays (base, triggers + alerts)
  await clickNav(page, "Overlays");
  await shot(page, path.join(OUT, "components", "overlays.png"));

  // 11b. Overlays: modal open state
  await page.getByRole("button", { name: "Open modal", exact: true }).click();
  await page.waitForTimeout(400);
  await shot(page, path.join(OUT, "components", "overlays-modal-open.png"));
  await page.keyboard.press("Escape");
  await page.waitForTimeout(300);

  // 11c. Overlays: drawer open state
  await page.getByRole("button", { name: "Open drawer", exact: true }).click();
  await page.waitForTimeout(400);
  await shot(page, path.join(OUT, "components", "overlays-drawer-open.png"));
  await page.keyboard.press("Escape");
  await page.waitForTimeout(300);

  // 12. States
  await clickNav(page, "States");
  await shot(page, path.join(OUT, "components", "states.png"));

  await browser.close();
  console.log("ALL DONE");
})().catch((e) => {
  console.error("SCREENSHOT SCRIPT FAILED", e);
  process.exit(1);
});

