      "nx-dur-1": { "value": "120ms", "note": "state: hover, press, colour" },
      "nx-dur-2": { "value": "180ms", "note": "movement: reveal, tab, row" },
      "nx-dur-3": { "value": "240ms", "note": "surface: drawer, modal, wizard" }
    },
    "easing": {
      "nx-ease":     { "value": "cubic-bezier(0.2, 0, 0, 1)" },
      "nx-ease-out": { "value": "cubic-bezier(0.16, 1, 0.3, 1)" },
      "nx-ease-in":  { "value": "cubic-bezier(0.7, 0, 0.84, 0)" }
    },
    "_note": "Reduced motion is off by default and nothing opts back in except opacity; animations hold their final keyframe (animation-fill-mode: forwards) under prefers-reduced-motion."
  },
  "zIndex": {
    "nx-z-base":    { "value": 0 },
    "nx-z-raised":  { "value": 10 },
    "nx-z-sticky":  { "value": 20 },
    "nx-z-scrim":   { "value": 30, "note": "the drawer's backdrop sits BELOW the drawer" },
    "nx-z-rail":    { "value": 40, "note": "...and the drawer above it, or the nav is untappable" },
    "nx-z-overlay": { "value": 50 },
    "nx-z-toast":   { "value": 60 },
    "nx-z-tooltip": { "value": 70 }
  },
  "focus": {
    "nx-focus-width":  { "value": "2px" },
    "nx-focus-offset": { "value": "2px" },
    "_note": "One global focus style: outline: var(--nx-focus-width) solid var(--color-signal-edge); outline-offset: var(--nx-focus-offset)."
  },
  "breakpoints": {
    "sm":  { "value": "40rem",  "px": 640 },
    "md":  { "value": "48rem",  "px": 768 },
    "lg":  { "value": "64rem",  "px": 1024 },
    "xl":  { "value": "80rem",  "px": 1280 },
    "2xl": { "value": "96rem",  "px": 1536 }
  },
  "surfaceArchetypes": {
    "_note": "Four surface archetypes — a border means 'separate object', spent by role.",
    "object": "Notched (chamfer via --nx-notch), owns a filament. Uses .nx-object.",
    "container": "Groups information without claiming to be an object. background: --color-surface, 1px --color-hairline border, radius-lg.",
    "plate": "Recessed. Technical values live here and nowhere else. background: --color-plate, font-mono, text-code, ink-secondary.",
    "rule": "A labelled hairline. The primary grouping device — most sections need no border at all."
  }
}

